#!/bin/sh
# Generated by FWShift: rows for the packet filter (and NAT) of a Phoenix Contact mGuard, added with gaiconfig.
# Read the report first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE            prints the gaiconfig calls; runs anywhere
#   sh THIS_FILE                      on the mGuard (SSH, as root or admin): adds the groups and rows
#   FWSHIFT_APPEND=yes sh THIS_FILE   also when the tables have rows: the new ones go after them
#
# Nothing is changed or deleted, and no interface, route or access to the mGuard is touched. Every call but the last
# writes with --silent; the last one reconfigures, and the rows take effect then. A call gaiconfig refuses stops the
# script: what was written before is stored but not active (the groups start with 'fws_', the rows' comments
# with the names of the rules); remove it in the web interface, or run the script again after fixing the cause.
set -u
DRY_RUN="${DRY_RUN:-}"
FWSHIFT_APPEND="${FWSHIFT_APPEND:-}"
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
gc() {
  if [ -n "$DRY_RUN" ]; then printf 'gaiconfig' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gaiconfig "$@" >/dev/null || fail "gaiconfig $*"
}
rows() {
  if [ -n "$DRY_RUN" ]; then echo 0; return 0; fi
  gaiconfig --get-rowcount "$1" || fail "gaiconfig --get-rowcount $1"
}
named() {
  [ -z "$DRY_RUN" ] && gaiconfig --get "$1" 2>/dev/null | grep -F -q "NAME = \"$2\""
}
if [ -z "$DRY_RUN" ] && ! command -v gaiconfig >/dev/null 2>&1; then fail "gaiconfig not found: run this on the mGuard"; fi
for t in FW_INCOMING FW_INCOMING_WAN_DMZ FW_INCOMING_DMZ_LAN FW_OUTGOING_DMZWAN FW_OUTGOING_LANDMZ FW_1TO1_NAT FW_NAT; do
  n=$(rows "$t")
  if [ "$n" != 0 ] && [ "$FWSHIFT_APPEND" != yes ]; then
    fail "$t has $n rows, which the mGuard would check before the new ones; nothing was written (FWSHIFT_APPEND=yes adds after them)"
  fi
done
named FW_GROUP_IP fws_outside_access_in-1_dst && fail 'an IP group named fws_outside_access_in-1_dst exists; nothing was written'
named FW_GROUP_PORT fws_mail-services && fail 'a port group named fws_mail-services exists; nothing was written'
named FW_GROUP_PORT fws_dns-ntp && fail 'a port group named fws_dns-ntp exists; nothing was written'
named FW_GROUP_PORT fws_web-ports && fail 'a port group named fws_web-ports exists; nothing was written'
named FW_GROUP_IP fws_internal && fail 'an IP group named fws_internal exists; nothing was written'
named FW_GROUP_IP fws_admin-range && fail 'an IP group named fws_admin-range exists; nothing was written'
named FW_GROUP_IP fws_dmz-servers && fail 'an IP group named fws_dmz-servers exists; nothing was written'
named FW_GROUP_IP fws_updates && fail 'an IP group named fws_updates exists; nothing was written'

# FW_GROUP_IP
N=$(rows FW_GROUP_IP)
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_outside_access_in-1_dst --set .COMMENT 'FWShift: web-srv, web-public'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.10
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 203.0.113.10
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_internal --set .COMMENT 'FWShift: internal'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.10.0.0/16
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.10
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.25
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.50
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.40.0.0/16
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_admin-range --set .COMMENT 'FWShift: admin-range'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.10.5.10-10.10.5.20
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_dmz-servers --set .COMMENT 'FWShift: dmz-servers'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.10
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.25
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.50
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_updates --set .COMMENT 'FWShift: updates'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP updates.example.com
N=$((N+1))

# FW_GROUP_PORT
N=$(rows FW_GROUP_PORT)
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_mail-services --set .COMMENT 'FWShift: mail-services'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 25
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 587
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 8443
N=$((N+1))
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_dns-ntp --set .COMMENT 'FWShift: dns-ntp'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 53
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 123
N=$((N+1))
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_web-ports --set .COMMENT 'FWShift: web-ports'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 80
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 8000-8010
N=$((N+1))

# FW_INCOMING
N=$(rows FW_INCOMING)
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG yes --set .COMMENT outside_access_in-4
N=$((N+1))

# FW_INCOMING_WAN_DMZ
N=$(rows FW_INCOMING_WAN_DMZ)
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 8080 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'outside_access_in-1: Published web server'
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.IN_IP" fws_outside_access_in-1_dst
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 10.20.0.25 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT outside_access_in-2
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.IN_PORT" fws_mail-services
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG yes --set .COMMENT outside_access_in-4
N=$((N+1))

# FW_INCOMING_DMZ_LAN
N=$(rows FW_INCOMING_DMZ_LAN)
gc --silent --goto FW_INCOMING_DMZ_LAN --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 10.10.0.0/16 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG yes --set .COMMENT dmz_access_in-3
N=$((N+1))

# FW_OUTGOING_DMZWAN
N=$(rows FW_OUTGOING_DMZWAN)
gc --silent --goto FW_OUTGOING_DMZWAN --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 10.10.0.0/16 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG yes --set .COMMENT dmz_access_in-3
N=$((N+1))

# FW_OUTGOING_LANDMZ
N=$(rows FW_OUTGOING_LANDMZ)
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 22 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT inside_access_in-3
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.FROM_IP" fws_admin-range
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.IN_IP" fws_dmz-servers
N=$((N+1))
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO tcp --set .FROM_IP 10.10.0.0/16 --set .FROM_PORT any --set .IN_IP 10.20.0.50 --set .IN_PORT 5060 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT inside_access_in-6
N=$((N+1))
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO udp --set .FROM_IP 10.10.0.0/16 --set .FROM_PORT any --set .IN_IP 10.20.0.50 --set .IN_PORT 5060 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT inside_access_in-6
N=$((N+1))

# FW_1TO1_NAT
N=$(rows FW_1TO1_NAT)
gc --silent --goto FW_1TO1_NAT --add-row --set .LOCAL_NET 10.20.0.25 --set .REMOTE_NET 203.0.113.25 --set .MASK 32 --set .ENABLE_ARP yes --set .COMMENT nat-mail-srv
N=$((N+1))

# FW_NAT
N=$(rows FW_NAT)
gc --goto FW_NAT --add-row --set .EXT_IF ext1 --set .IN_IP 10.10.0.0/16 --set .COMMENT nat-inside-net
N=$((N+1))

if [ -z "$DRY_RUN" ]; then
  for v in FW_INCOMING_GLOBAL FW_OUTGOING_GLOBAL; do
    g=$(gaiconfig --get "$v" 2>/dev/null || true)
    [ "$g" = rules ] || printf 'NOTE: %s is %s: the rows take effect only with "Use the firewall ruleset below" (rules)\n' "$v" "$g" >&2
  done
fi
echo 'Done. Check the tables in the web interface (Network Security >> Packet Filter, Network >> NAT).' >&2
